// Calculate extent of the bounding box
const T extent[3] = {
    bmax[0] - bmin[0],
    bmax[1] - bmin[1],
    bmax[2] - bmin[2]
};

// Initialize minimum cost and axis
T min_cost = std::numeric_limits<T>::max();
int min_cost_axis = 0;

// Check each axis for potential split
for (int axis = 0; axis < 3; ++axis) {
    // Skip axis with zero extent
    if (extent[axis] < std::numeric_limits<T>::epsilon()) {
        continue;
    }

    // Calculate bin size along current axis
    const int bin_count = bins->binSize[axis];
    if (bin_count <= 1) {
        continue;
    }

    // Initialize left and right bounding boxes and counts
    StackContainer<std::vector<BBox<T>>, 32> left_bboxes;
    StackContainer<std::vector<BBox<T>>, 32> right_bboxes;
    StackContainer<std::vector<int>, 32> left_counts;
    StackContainer<std::vector<int>, 32> right_counts;

    left_bboxes->resize(bin_count);
    right_bboxes->resize(bin_count);
    left_counts->resize(bin_count, 0);
    right_counts->resize(bin_count, 0);

    // Initialize left and right bounding boxes
    for (int i = 0; i < bin_count; ++i) {
        left_bboxes->at(i) = BBox<T>();
        right_bboxes->at(i) = BBox<T>();
    }

    // Calculate left and right bounding boxes and counts
    const Bin<T>* bin_data = bins->GetBin(axis);
    for (int i = 0; i < bin_count; ++i) {
        const Bin<T>& bin = bin_data[i];
        left_counts->at(i) = bin.enter;
        right_counts->at(bin_count - 1 - i) = bin.exit;

        if (i > 0) {
            left_bboxes->at(i) = left_bboxes->at(i - 1);
            left_bboxes->at(i).Expand(bin.bbox);
        } else {
            left_bboxes->at(i) = bin.bbox;
        }

        if (i < bin_count - 1) {
            right_bboxes->at(bin_count - 1 - i) = right_bboxes->at(bin_count - i);
            right_bboxes->at(bin_count - 1 - i).Expand(bin.bbox);
        } else {
            right_bboxes->at(bin_count - 1 - i) = bin.bbox;
        }
    }

    // Calculate cost for each split plane
    for (int i = 0; i < bin_count - 1; ++i) {
        const int left_count = left_counts->at(i);
        const int right_count = right_counts->at(i + 1);

        if (left_count == 0 || right_count == 0) {
            continue;
        }

        const T left_sa = left_bboxes->at(i).SurfaceArea();
        const T right_sa = right_bboxes->at(i + 1).SurfaceArea();
        const T total_sa = BBox<T>(bmin, bmax).SurfaceArea();

        const T cost = (left_sa / total_sa) * static_cast<T>(left_count) +
                       (right_sa / total_sa) * static_cast<T>(right_count);

        if (cost < min_cost) {
            min_cost = cost;
            min_cost_axis = axis;
            cut_pos[axis] = bmin[axis] + extent[axis] * (static_cast<T>(i + 1) / static_cast<T>(bin_count));
        }
    }
}

*minCostAxis = min_cost_axis;

// Return true if a valid split was found
return min_cost < std::numeric_limits<T>::max();

